# hypothesis: flood propagation of symmetry: for every 2-cell, take value from nearest non-2 among h/v/diag neighbors iteratively
def solve(g):
    O=[r[:] for r in g]; changed=True
    while changed:
        changed=False
        for i in range(N):
            for j in range(N):
                if O[i][j]!=2: continue
                cands=[]
                for dj in (-1,1):
                    for di in (-1,1):
                        x,y=i+di,j+dj
                        if 0<=x<N and 0<=y<N and O[x][y]!=2: cands.append(O[x][y]); break
                for dj in (-1,1):
                    y=j+dj
                    if 0<=y<N and O[i][y]!=2: cands.append(O[i][y])
                for di in (-1,1):
                    x=i+di
                    if 0<=x<N and O[x][j]!=2: cands.append(O[x][j])
                for dj in (-1,1):
                    y=j+dj
                    if 0<=y<N and O[i][y]!=2: cands.append(O[i][y])
                if cands:
                    vals=collections.Counter(cands).most_common()
                    O[i][j]=vals[0][0]
                    changed=True
    return O==out
