def bfs_nearest(g,neigh):
    n=len(g);O=[r[:] for r in g];dist={};q=deque()
    for i in range(n):
        for j in range(n):
            if g[i][j]!=2: dist[(i,j)]=0; q.append((i,j))
    while q:
        i,j=q.popleft()
        vals=[]
