def syms(g,n):
    s=[]
    if g==g[::-1]: s.append('rowrev')
    if g==zip(*g)[::-1]: pass
    hr=[r[::-1] for r in g]
    vr=[[g[n-1-r][c] for c in range(n)] for r in range(n)]
    if g==hr: s.append('hflip')
    if g==vr: s.append('vflip')
    if [[g[n-1-r][n-1-c] for c in range(n)] for r in range(n)]==g: s.append('pflip')
    return s
